/* EOSDO visible diagnostics */
function renderDiagnostics(){let el=$("#diagnosticsResult");if(!el)return;let r=eosdoSelfCheck(),tests=[["Основные экраны",r.ok],["Создание документа",!!$("#newDoc")&&!!$("#createDlg")&&!!$("#createForm")],["Реестр документов",!!$("#docsView")&&!!$("#docTable")],["Задачи",!!$("#tasksView")&&!!$("#taskList")],["Отчёты",!!$("#reportsView")&&!!$("#reportWorkspace")],["МЭДО",!!$("#medoView")&&!!$("#medoList")],["Архив",!!$("#archiveView")&&!!$("#orgarchiveView")],["Аудит",!!$("#auditView")&&!!$("#auditTable")]];el.innerHTML=tests.map(x=>`<div class="row"><div><strong>${x[0]}</strong><span>${x[1]?"Компоненты найдены":"Ошибка конфигурации"}</span></div><span class="badge ${x[1]?"reg":"rework"}">${x[1]?"OK":"Ошибка"}</span></div>`).join("")+`<p><small>Проверено: ${new Date().toLocaleString("ru-RU")}</small></p>`}
document.addEventListener("click",e=>{if(e.target.closest("[data-run-selfcheck]")){renderDiagnostics();toast("Самопроверка завершена")}if(e.target.closest('[data-view="diagnostics"]'))setTimeout(renderDiagnostics,0)});
renderDiagnostics();


/* EOSDO workflow smoke checks */
function workflowSmokeCheck(){let checks=[];function add(name,ok){checks.push({name,ok:!!ok})}add("Навигация",$$("[data-view]").length>0&&$$(".view").length>0);add("Создание документа",!!$("#newDoc")&&!!$("#createForm")&&!!$("#createDlg"));add("Карточка документа",typeof openDoc==="function"&&!!$("#drawer"));add("Поиск",!!$("#q")&&!!$("#docTable"));add("МЭДО",!!$("#medoView")&&typeof renderMedo==="function");add("Отчёты",!!$("#reportsView")&&typeof renderReport==="function");add("Архив",!!$("#archiveView")&&!!$("#orgarchiveView"));add("УКЭП",typeof signaturePanel==="function");add("Справочники",typeof renderDict==="function"&&typeof renderOrgs==="function");return checks}
const oldRenderDiagnostics=renderDiagnostics;renderDiagnostics=function(){oldRenderDiagnostics();let el=$("#diagnosticsResult");if(!el)return;let checks=workflowSmokeCheck();el.insertAdjacentHTML("beforeend","<h3>Сквозная проверка модулей</h3>"+checks.map(x=>`<div class="row"><strong>${x.name}</strong><span class="badge ${x.ok?"reg":"rework"}">${x.ok?"OK":"Ошибка"}</span></div>`).join(""))};


/* EOSDO release readiness */
function releaseReadiness(){let checks=workflowSmokeCheck(),bad=checks.filter(x=>!x.ok);return {ok:bad.length===0,checks,failed:bad.map(x=>x.name),version:"0.9.5",at:new Date().toLocaleString("ru-RU")}}
function renderReleaseReadiness(){let el=$("#diagnosticsResult");if(!el)return;let r=releaseReadiness();el.insertAdjacentHTML("beforeend",`<h3>Готовность сборки</h3><div class="row"><div><strong>EOSDO-Lite ${r.version}</strong><span>${r.ok?"Критические компоненты конфигурации найдены":"Есть ошибки конфигурации: "+r.failed.join(", ")}</span></div><span class="badge ${r.ok?"reg":"rework"}">${r.ok?"READY":"CHECK"}</span></div>`)}
const readinessDiagnostics=renderDiagnostics;renderDiagnostics=function(){readinessDiagnostics();renderReleaseReadiness()};


/* EOSDO final data consistency checks */
function dataConsistencyCheck(){let issues=[];let ids=new Set();docs.forEach(d=>{if(!d.id)issues.push("Документ без ID");else if(ids.has(d.id))issues.push("Дублирующий ID "+d.id);else ids.add(d.id);if(!d.number)issues.push("Документ без номера: "+(d.title||d.id));if(!d.type)issues.push("Документ без типа: "+(d.number||d.id));(d.links||[]).forEach(l=>{if(l.id&&!docs.some(x=>x.id===l.id))issues.push("Битая связь у "+d.number)})});return {ok:issues.length===0,issues}}
const finalReadiness=releaseReadiness;releaseReadiness=function(){let r=finalReadiness(),dc=dataConsistencyCheck();return {...r,ok:r.ok&&dc.ok,dataConsistency:dc,failed:[...r.failed,...(dc.ok?[]:["Целостность данных"])]}}


/* EOSDO final release gate */
function finalReleaseGate(){let smoke=workflowSmokeCheck(),data=dataConsistencyCheck(),requiredTypes=["Распорядительный документ","Договор","Входящий документ","Исходящий документ","Лист исполнения"],typeCoverage=requiredTypes.every(t=>Object.keys(typeFieldMap).includes(t));let checks=[...smoke,{name:"Целостность данных",ok:data.ok},{name:"Маршруты основных типов",ok:typeCoverage},{name:"Аудит действий",ok:typeof logAudit==="function"},{name:"Регистрация и исполнение",ok:typeof ensureExecution==="function"},{name:"Архивное хранение",ok:typeof ensureArchiveDoc==="function"},{name:"Электронная подпись",ok:typeof signaturePanel==="function"},{name:"МЭДО",ok:typeof renderMedo==="function"}];return {ok:checks.every(x=>x.ok),checks,version:"1.0.0",failed:checks.filter(x=>!x.ok).map(x=>x.name)}}
window.EOSDO.releaseGate=finalReleaseGate;
const finalDiagnostics=renderDiagnostics;renderDiagnostics=function(){finalDiagnostics();let el=$("#diagnosticsResult");if(!el)return;let r=finalReleaseGate();el.insertAdjacentHTML("beforeend",`<h3>Финальный контроль версии ${r.version}</h3>${r.checks.map(x=>`<div class="row"><strong>${x.name}</strong><span class="badge ${x.ok?"reg":"rework"}">${x.ok?"OK":"CHECK"}</span></div>`).join("")}<div class="row"><div><strong>${r.ok?"Функциональная сборка готова":"Требуется проверка"}</strong><span>${r.ok?"Все встроенные контрольные проверки пройдены":"Не пройдены: "+r.failed.join(", ")}</span></div><span class="badge ${r.ok?"reg":"rework"}">${r.ok?"1.0":"CHECK"}</span></div>`)}
